(function() {
    'use strict';

    class CafeEspecialidadAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Café de Especialidad';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 6000,
                    debt: 400000,
                    qualityScore: 38.5,
                    reputation: 40,
                    qualityPotential: 72,
                    investorShare: 0,
                    remediationInvested: 0,
                    annualRevenue: 0,
                    debtService: 74000,
                    clientName: '',
                    viabilityMargin: 0,
                    cashHistory: [],
                    qualityHistory: [],
                    reputationHistory: [],
                    revenueHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    remediationLevel: 'medium',
                    financingMethod: 'bank_loan',
                    fermentationProtocol: 'standard_48h',
                    dryingMethod: 'covered_patio',
                    independentCupping: 'yes',
                    clientChoice: 'forge_exclusive',
                    loanTerm: '15',
                    capexApproach: 'retained_plus_mortgage'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod;
            this._updateBriefing(state);

            if (period === 1) {
                var remInput = document.getElementById('remediationLevel');
                if (remInput) decisions.remediationLevel = remInput.value;
                var finInput = document.getElementById('financingMethod');
                if (finInput) decisions.financingMethod = finInput.value;
            } else if (period === 2) {
                var fermInput = document.getElementById('fermentationProtocol');
                if (fermInput) decisions.fermentationProtocol = fermInput.value;
                var dryInput = document.getElementById('dryingMethod');
                if (dryInput) decisions.dryingMethod = dryInput.value;
                var cupInput = document.getElementById('independentCupping');
                if (cupInput) decisions.independentCupping = cupInput.value;
            } else if (period === 3) {
                var clientInput = document.getElementById('clientChoice');
                if (clientInput) decisions.clientChoice = clientInput.value;
            } else if (period === 4) {
                var termInput = document.getElementById('loanTerm');
                if (termInput) decisions.loanTerm = termInput.value;
                var capexInput = document.getElementById('capexApproach');
                if (capexInput) decisions.capexApproach = capexInput.value;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var revenue = 0;
            var costs = 0;
            var reputationDelta = 0;

            if (period === 1) {
                var remCost = 0;
                if (d.remediationLevel === 'full') {
                    remCost = 171000;
                    ds.qualityPotential = 86;
                } else if (d.remediationLevel === 'medium') {
                    remCost = 100000;
                    ds.qualityPotential = 81;
                } else {
                    remCost = 50000;
                    ds.qualityPotential = 76;
                }

                if (d.financingMethod === 'bank_loan') {
                    ds.debt += remCost;
                } else if (d.financingMethod === 'investor') {
                    ds.investorShare = 0.25;
                    ds.debt += Math.round(remCost * 0.3);
                } else {
                    var affordable = Math.min(remCost, ds.cash);
                    costs = affordable;
                    if (affordable < remCost) {
                        ds.qualityPotential = Math.min(ds.qualityPotential, 76);
                    }
                }

                ds.remediationInvested = remCost;
                ds.cash -= costs;
                reputationDelta = -5;
                ds.reputation = Math.max(0, ds.reputation + reputationDelta);
                ds.qualityScore = Math.round((ds.qualityPotential - 10) * 10) / 10;

            } else if (period === 2) {
                var protocolBonus = 0;

                if (d.fermentationProtocol === 'strict_60h') {
                    protocolBonus += 4;
                } else if (d.fermentationProtocol === 'standard_48h') {
                    protocolBonus += 2;
                } else {
                    protocolBonus -= 2;
                }

                if (d.dryingMethod === 'climate_controlled') {
                    protocolBonus += 4;
                } else if (d.dryingMethod === 'covered_patio') {
                    protocolBonus += 2;
                } else {
                    protocolBonus -= 1;
                }

                costs = 1500;
                if (d.independentCupping === 'yes') {
                    costs += 3000;
                    protocolBonus += 2;
                    reputationDelta = 8;
                }

                ds.qualityScore = Math.min(96, ds.qualityPotential + protocolBonus);
                ds.qualityScore = Math.round(ds.qualityScore * 10) / 10;
                ds.cash -= costs;
                ds.reputation = Math.min(100, Math.max(0, ds.reputation + reputationDelta));

            } else if (period === 3) {
                var score = ds.qualityScore;
                var annualRev = 0;
                var clientLabel = '';

                if (d.clientChoice === 'forge_exclusive') {
                    if (score >= 85) {
                        annualRev = 5.50 * 14400;
                        clientLabel = 'Forge & Flame (Premium)';
                        reputationDelta = 15;
                    } else if (score >= 80) {
                        annualRev = 4.50 * 14400;
                        clientLabel = 'Forge & Flame (Standard)';
                        reputationDelta = 8;
                    } else {
                        annualRev = 2.50 * 14400;
                        clientLabel = 'Commodity Fallback';
                        reputationDelta = -15;
                    }
                } else if (d.clientChoice === 'seattle_portland') {
                    if (score >= 80) {
                        annualRev = (4.20 * 12000) + (4.00 * 2400);
                        clientLabel = 'Seattle + Portland';
                        reputationDelta = 5;
                    } else {
                        annualRev = (3.50 * 12000) + (3.20 * 2400);
                        clientLabel = 'Seattle + Portland (reduced)';
                        reputationDelta = -5;
                    }
                } else {
                    if (score >= 85) {
                        annualRev = (5.50 * 2400) + (4.20 * 12000);
                        clientLabel = 'Forge & Flame + Seattle';
                        reputationDelta = 12;
                    } else if (score >= 80) {
                        annualRev = (4.50 * 2400) + (4.20 * 12000);
                        clientLabel = 'Forge & Flame + Seattle';
                        reputationDelta = 6;
                    } else {
                        annualRev = (2.50 * 2400) + (3.50 * 12000);
                        clientLabel = 'Commodity + Seattle (reduced)';
                        reputationDelta = -10;
                    }
                }

                if (ds.investorShare > 0) {
                    annualRev = annualRev * (1 - ds.investorShare);
                }

                ds.annualRevenue = Math.round(annualRev);
                ds.clientName = clientLabel;
                revenue = Math.round(annualRev);
                var quarterPayment = Math.round(annualRev / 4);
                ds.cash += quarterPayment;
                ds.reputation = Math.min(100, Math.max(0, ds.reputation + reputationDelta));

            } else if (period === 4) {
                var term = parseInt(d.loanTerm) || 15;

                if (d.capexApproach === 'new_loan') {
                    ds.debt += 50000;
                    costs = 2000;
                } else if (d.capexApproach === 'retained_plus_mortgage') {
                    costs = 5000;
                } else {
                    costs = 3000;
                    if (ds.investorShare === 0) {
                        ds.investorShare = 0.15;
                        ds.annualRevenue = Math.round(ds.annualRevenue * 0.85);
                    }
                }

                var annualInterest = Math.round(ds.debt * 0.085);
                var annualPrincipal = Math.round(ds.debt / term);
                var debtServ = annualInterest + annualPrincipal;
                ds.debtService = debtServ;

                ds.cash -= costs;
                var qtrRev = Math.round(ds.annualRevenue / 4);
                ds.cash += qtrRev;
                revenue = ds.annualRevenue;

                var opCosts = 20000;
                ds.viabilityMargin = ds.annualRevenue - debtServ - opCosts;
            }

            ds.cashHistory.push(ds.cash);
            ds.qualityHistory.push(ds.qualityScore);
            ds.reputationHistory.push(ds.reputation);
            ds.revenueHistory.push(revenue);

            // v1.1.0 P0 FIX: render next round's decision panel synchronously. Old setTimeout
            // fired AFTER the framework incremented state.currentPeriod, so (currentPeriod + 1)
            // overshot by one and showed the wrong panel (round N+2) for rounds 2-4, hiding the
            // real controls (which then submitted defaults). Pre-increment here, currentPeriod is
            // still N so (N + 1) targets the correct next round.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });

            return {
                period: period,
                revenue: revenue,
                costs: costs,
                cash: ds.cash,
                qualityScore: ds.qualityScore,
                reputation: ds.reputation,
                debt: ds.debt,
                annualRevenue: ds.annualRevenue,
                debtService: ds.debtService
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('debtDisplay', 'domainState.debt',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('qualityDisplay', 'domainState.qualityScore',
                (v) => typeof v === 'number' ? v.toFixed(1) : v);
            uiManager.bind('reputationDisplay', 'domainState.reputation',
                (v) => Math.round(v) + '%');

            // v1.1.0 FIX: framework Undo restores state/KPIs but not this sim's decision panels.
            // Re-render the restored round's panel (deferred, after the framework undo handler).
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn) {
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        if (window.mySimulation && window.mySimulation.state) {
                            self._updateBriefing(window.mySimulation.state);
                        }
                    }, 0);
                });
            }
        }

        getChartConfig() {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            return {
                performanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_quality_series'),
                            data: [],
                            borderColor: '#2E7D32',
                            backgroundColor: 'rgba(46,125,50,0.08)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            pointBackgroundColor: '#2E7D32',
                            pointRadius: 5,
                            pointHoverRadius: 7,
                            yAxisID: 'y'
                        }, {
                            label: t('chart_reputation_series'),
                            data: [],
                            borderColor: '#FF8F00',
                            backgroundColor: 'rgba(255,143,0,0.08)',
                            borderWidth: 3,
                            fill: false,
                            tension: 0.3,
                            pointBackgroundColor: '#FF8F00',
                            pointRadius: 5,
                            pointHoverRadius: 7,
                            yAxisID: 'y'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: {
                                display: true,
                                text: t('chart_title'),
                                font: { size: 14, family: 'Georgia, serif' },
                                color: '#3E2723'
                            },
                            legend: {
                                labels: {
                                    font: { size: 12 },
                                    color: '#5D4037',
                                    usePointStyle: true
                                }
                            }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 100,
                                title: {
                                    display: true,
                                    text: t('chart_axis_score'),
                                    color: '#5D4037'
                                },
                                grid: {
                                    color: 'rgba(0,0,0,0.06)'
                                }
                            },
                            x: {
                                grid: {
                                    display: false
                                }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.qualityHistory.map(function(_, i) {
                return 'R' + (i + 1);
            });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.qualityHistory },
                        { data: state.domainState.reputationHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var lastRecord = history[history.length - 1];
            var res = lastRecord.results || {};
            var finalQuality = res.qualityScore || 0;
            var finalReputation = res.reputation || 0;
            var finalRevenue = res.annualRevenue || 0;
            var finalDebtService = res.debtService || 74000;
            var finalDebt = res.debt || 400000;
            var finalCash = res.cash || 0;

            var opCosts = 20000;
            var netViability = finalRevenue - finalDebtService - opCosts;

            var performance = t('perf_needs');
            var insights = [];

            if (finalQuality >= 85 && netViability > 0 && finalReputation >= 60) {
                performance = t('perf_excellent');
                insights.push(t('insight_excellent'));
            } else if (finalQuality >= 80 && netViability > -10000 && finalReputation >= 45) {
                performance = t('perf_good');
                insights.push(t('insight_good'));
            } else if (finalQuality >= 75) {
                performance = t('perf_developing');
                insights.push(t('insight_developing'));
            } else {
                insights.push(t('insight_poor'));
            }

            if (netViability < 0) {
                insights.push(t('insight_debt'));
            }

            return {
                finalQuality: finalQuality,
                finalReputation: finalReputation,
                annualRevenue: finalRevenue,
                debtService: finalDebtService,
                netViability: netViability,
                totalDebt: finalDebt,
                cashPosition: finalCash,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.currentPeriod === 1 && results.qualityScore < 72) {
                return window.mySimulation.t('hint_low_investment');
            }
            if (state.currentPeriod === 2 && results.qualityScore < 80) {
                return window.mySimulation.t('hint_quality_gap');
            }
            if (state.currentPeriod === 3 && results.annualRevenue < 50000) {
                return window.mySimulation.t('hint_low_revenue');
            }
            if (state.currentPeriod === 4) {
                var viability = (results.annualRevenue || 0) - (results.debtService || 74000) - 20000;
                if (viability < 0) {
                    return window.mySimulation.t('hint_not_viable');
                }
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.qualityScore', label: 'SCA Score', i18nKey: 'col_quality', formatter: function(v) { return v ? v.toFixed(1) : '-'; } },
